DE_SOTO_EM_2 = {
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_21'): 'Was?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_22'): 'Ich verstehe... Der arme Vater von Kaimaru ist tot.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_23'): 'Ishimaru hatte schon seit längerer Zeit öffentlich\ndie Methoden des Bosses abgelehnt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_24'): 'Er glaubte, die Menschen müssten mit allen Mitteln\nüberleben, und dass unser einziges Ziel als Gruppe\nsein sollte, stärker zu werden.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_25'): 'Er mischte sich sogar in den Sklavenhandel ein.\nMyrthe, Kinta und Yui waren Teil seiner\n"Ware."',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_26'): 'Ich hatte nicht die Kraft, Ishimaru zu besiegen.\nMeine einzige Option war, ihnen zur Flucht zu verhelfen.\nWir flohen tagelang durch die Berge.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_27'): 'Aus dem dichten Nebel heraus kamen wir an\nder Schwebenden Brücke des Himmels an.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_28'): 'Mit Ishimaru hinter dir, hm?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_29'): 'Lady Sakuna!\nIch bitte demütig um Entschuldigung, dich\neinstweilen erneut damit zu belästigen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_30'): 'Aber wenn derjenige, der die Dämonen kontrolliert,\nwirklich Ishimaru ist, dann bitte... finde einen Weg,\nihm das Leben zu schonen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_31'): 'D-Das Knien ist nun wirklich genug.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_32'): 'Ich verstehe nicht, warum dir das Wohlbefinden\ndieses Ishimaru so am Herzen liegt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_33'): 'Die Flammen des Konflikts nahmen ihm alles,\nso wie sie es Kinta und Yui nahmen.\nDer Krieg veränderte ihn. Er ließ ihn gebrochen und allein.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_34'): 'Ich bin ein Samurai, und doch fehlt mir allein\ndie Kraft, ihm zu helfen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_35'): 'Wenn es noch einen Weg gibt, Ishimaru vom Pfad\nder Selbstzerstörung abzuhalten,\n dann FINDE ich ihn, egal was es kostet!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_36'): 'Barmherzig. Nimm den Melodramatismus etwas zurück, bitte?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_37'): 'Keine Angst. Ich werde dir deinen Wunsch erfüllen.\nIch bin schließlich eine Göttin.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_38'): 'Alles natürlich unter der Annahme, dass der Anführer\nder Dämonen tatsächlich Ishimaru ist.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_39'): 'Meine Frau...! Ich kann dir gar nicht genug danken!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_40'): 'Igitt! Wie gesagt, das ist völlig unnötig!\nSteh schon auf!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_41'): 'Du musst dich selbst höher einschätzen.\nDie anderen vertrauen dir mehr, als du denkst.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_42'): 'D-Denkst du das wirklich?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000201_43'): 'Ja.\nIch werde mich auf dich verlassen, Tauemon.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701a_0'): 'Wa--?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701a_1'): 'Was... Was ist hier passiert?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701b_0'): 'Das Haus... Es ist weg! Alles ist weg!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701b_1'): 'Wo ist jeder?! Was ist passiert?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701b_2'): 'Ashigumo! Diese Wunden...\nGeht es den anderen gut?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701b_3'): 'Das ist nichts. Schlimmeres habe ich überstanden.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701b_4'): 'Die Dämonen... griffen den Pass mit voller Wucht an.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701b_5'): 'Ich konnte allen zur Flucht verhelfen,\naber ich konnte das Haus und die Felder nicht schützen.\nVergib mir.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701b_6'): 'Also leben sie alle?! Gott sei Dank!\nWo sind sie jetzt?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000701b_7'): 'In einer nahegelegenen Höhle. Folge mir.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_0'): 'Willkommen zurück, Lady Sakuna.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_1'): 'Yo. Du bist spät.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_10'): 'Wir haben alles besprochen und beschlossen, wieder aufzubauen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_11'): 'Wir dachten, es sei am besten, mit einer\nWohnung zu beginnen, also fingen wir sofort an,\naber meine linken Hände haben uns ausgebremst.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_12'): 'Bitte baut uns ein echtes Haus!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_13'): 'Undichte Dächer und löchrige Wände\nstören uns nicht. Wir sind auf alles gefasst!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_14'): 'Jaa, jaa!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_15'): 'Alle... *schnüff*',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_16'): 'Prinzessin...\nIch wusste, dass du zu uns zurückkehrst.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_17'): 'Erlebt den unbeugsamen Geist der Menschenkinder.\nWir Götter dürfen ihnen nicht nachstehen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_18'): 'In der Tat. Du könntest nicht recht haben.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_2'): 'Wir haben alle auf dich gewartet, Göttin!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_3'): 'Juhu!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_4'): 'Willkommen, Sakuna. Wer ist diese Person?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_5'): 'Es freut mich, dich kennenzulernen.\nIch nenne mich Prinzessin Kokorowa, Sakunas liebe Freundin.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_6'): 'Was?! Du hast tatsächlich eine Freundin?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_7'): 'W-Welche Unverschämtheit! Sei still, du!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_8'): 'Wichtiger noch: Was ist das hier?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:05000704_9'): 'Mmm, nun...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_0'): 'Nun also... Wo beginnen wir?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_1'): 'Whoa! Der Boden ist klebrig!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_10'): 'Fluten wir die Felder und pflügen sie,\nsinkt der schwere Boden ab, und die Asche\nwäscht sich womöglich einfach mit dem Wasser aus.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_11'): 'Du bist ein Genie!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_12'): '*kichert*',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_13'): 'In Ordnung. Ich entferne die großen Steine,\nfülle das Feld mit Wasser und pflüge den Boden.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_2'): 'Der Düngergehalt ist erstaunlich niedrig.\nIst das wirklich eine Folge des Ascheregens?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_3'): 'Bei diesem Grad der Verseuchung\nmüssen wir womöglich den gesamten Boden austauschen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_4'): 'Würde das das Problem lösen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_5'): 'Nein... Es wäre eine Verbesserung,\ndoch Boden muss kultiviert werden.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_6'): 'Er wird nicht mehr wie vor dem Ausbruch sein.\nTauschen wir ihn aus, beginnen wir\nbei Null.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_7'): 'Dann lass uns zuerst einen Weg finden,\nnur die Asche aus dem Boden zu entfernen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_8'): 'Nur die Asche? Ist so etwas möglich?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000101_9'): 'Der Boden ist klebrig wegen des Ascheregens.\nMit anderen Worten: Die Asche ist im Wasser gelöst.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_0'): 'Wie sieht es aus?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_1'): 'Die Fruchtbarkeit des Feldes ist stark verbessert!\nEs ist weit entfernt von alterm Glanz, aber...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_10'): 'Wa--?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_11'): 'Vergib mir. Ich verliere mich sehr leicht in Gedanken.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_12'): 'Ehrlich gesagt, Kokorowa, es freut mich,\ndass deine Sorge um uns so weit reicht.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_13'): 'Wir sind dir zutiefst dankbar.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_14'): 'Mwaha!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_15'): '*hust* Ich kehre vorerst in die Hauptstadt zurück.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_16'): 'Wenn ich das Bücherhaus nutze,\nkann ich womöglich etwas Relevantes lernen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_17'): 'In Ordnung dann.\nPass auf dem Rückweg auf.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_2'): 'Hmmm. Es bleibt also noch ein Hindernis.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_3'): 'Wenn schon von Asche die Rede ist... Yanato ist ein\nLand voller Vulkane.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_4'): 'Auch Berge, die für uns jetzt friedlich wirken,\nbrachen in alter Zeit häufig aus.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_5'): 'War das gesamte Land Ascheregen ausgesetzt,\nwie bestimmten denn damals die Bauern,\nwelche Gebiete sich für den Anbau eigneten?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_6'): 'Wie sollte ich das wissen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_7'): 'Ein berechtigter Punkt... Gehen wir davon aus,\ndass Aschverseuchung den Boden für immer verdirbt,\nkönnte keines der beiden Reiche Anbau betreiben.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_8'): 'Da wir ABER Anbau betreiben können, muss es...\nNein, aber... Mit anderen Worten...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000102_9'): 'Kokorowa... In deine eigene kleine Welt zurückzuziehen,\nlöst keines unserer Probleme.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_0'): 'Oho. Wenn das nicht Ashigumo ist.\nDu bist also wieder gesund?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_1'): 'Mir geht es viel besser. Mythres Behandlung\nscheint gewirkt zu haben.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_10'): 'Igitt, was ist los mit dieser Insel?\nWie vielen Bedrohungen müssen wir begegnen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_11'): 'Ich erinnere mich nicht, dass es so mächtig war,\njedoch.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_12'): 'Omizuchi beanspruchte dieses Land zuerst,\nweswegen die Kraft des Feuergottes, der später kam,\ngeschwächt ist. Das würde es erklären.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_13'): 'Danke, Ashigumo, dass du uns benachrichtigt hast.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_14'): 'Es war wirklich nichts.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_15'): 'Ich werde wohl Vorkehrungen im Wald treffen müssen,\num sicherzustellen, dass unsere Lebensweise\nnicht erneut gestört wird.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_2'): 'Ich verstehe. Das ist wahrlich eine gute Nachricht.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_3'): 'Also, brauchst du etwas?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_4'): 'Ein Gespenst meiner Stammes schleicht\nrund um den östlichen Wald.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_5'): 'Es hat noch keinen Schaden angerichtet,\naber die Kappa sind voller Furcht und Unruhe.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_6'): 'Igitt, schon wieder.\nHier dachte ich, es wäre im Feuer umgekommen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_7'): 'Reichte das nicht, um es zu vernichten,\nmuss es ein hochrangiges Gespenst sein,\ndas Flammen nach seinem Willen lenken kann.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_8'): 'Ah! Es muss das Gespenst von Homusubi sein!\nEs schürt die Grollen der Toten mit\nunauslöschlichem Feuer und erzeugt neuen Tod.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000201_9'): 'Es ist eine mächtige Naturgewalt,\ndessen Kraft selbst mit Omizuchi mithalten kann.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_0'): 'Sah-Sah!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_1'): 'Ich hörte vom Eingang von Ashigumo, dass Kaimaru\nzusammengebrochen ist, und rannte so schnell\nich konnte hierher, aber...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_10'): 'Waaas?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_11'): 'Ich verstehe. Gleich wie Lady Toyohana.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_12'): 'Ja. Ganz wie Sakunas Mutter,\nLady Toyohana.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_13'): 'Das Verweilen im Erhabenen Reich hat den\nunverkennbaren Funken der Göttlichkeit in ihren\nsterblichen Körpern entzündet.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_14'): 'Ich bin überzeugt, dass hier etwas auf ihre\nNatur antwortet. Hast du eine Ahnung,\nwas es sein könnte?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_15'): 'Weißt du, manchmal habe ich das Gefühl,\nmein Schmiedehammer besteht aus reinem Licht.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_16'): 'Wenn das passiert, mache ich immer\netwas Besonderes Gutes.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_17'): 'Wenn du damit meinst, dann habe ich manchmal\ndas Gefühl, dass mein Webstuhl singt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_18'): 'Ich... kenne auf eine Art eine Krankheit,\ndie meine Medizin nicht erklären kann.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_19'): 'Und ich habe die kuriose Kraft erlangt,\nzwanzig Schalen Reis auf einmal zu essen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_2'): 'Er sieht gesund und munter aus.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_20'): 'Das ist eine völlig andere Sache!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_21'): 'Darum geht es doch gar nicht.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_22'): 'Und Kaimaru kann mit Tieren kommunizieren.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_23'): 'Ich glaube, was passiert ist, ist, dass in\neinem Moment großer Furcht sein Herz\nmit dem dieses Ishimaru-Menschen verwoben wurde.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_24'): 'Glücklicherweise scheint er das Schlimmste vermieden\nzu haben, doch wäre er unter die Kontrolle des\nDämonen geraten, der Herze verdirbt...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_25'): 'Er wäre vielleicht nicht mehr normal geworden?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_26'): 'Wie auch immer, es ist eine Erleichterung, dass er\nunversehrt ist, doch ihr alle habt eine Kraft\nangenommen, die der der Götter gleichkommt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_27'): 'Du musst lernen, sie so zu führen,\ndass sie von anderen nicht missbraucht wird.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_28'): 'Hab keine Angst. Wurdest du von einer ebenso\nbarmherzigen Göttin wie Lady Toyohana gesegnet,\nwirst du sicher gedeihen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_29'): 'Was du werden wirst, hängt allein\nvon deinen künftigen Taten ab.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_3'): 'Kaimaru ist nicht wegen Krankheit umgefallen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_30'): 'Hmmm...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_4'): 'Sein Herz ist fort.\nSo sah es aus.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_5'): '"Sein Herz ist fort"? Was bedeutet das?\nBist du nicht auch ein Arzt?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_6'): 'Die Medizin, die ich kenne, kann das nicht erklären.\nAber das ist, was ich fühlte. Sehr stark.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_7'): 'Faszinierend.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_8'): 'Was bedeutet das, Kokorowa?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000402_9'): 'Ich vermute, sie alle verwandeln sich langsam\nvon Menschen in Götter.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_0'): 'Du bist also zurück.\nWie lief deine Untersuchung?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_1'): 'Ich habe nahezu jeden Berg im Erhabenen\nund im Niedrigen Reich durchsucht.\nIch glaube, ich weiß, was wir tun müssen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_10'): 'Das bedeutet wohl, dass es kaum Ausbrüche gibt,\ndie groß genug wären, Asche über\nweite Strecken zu verstreuen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_11'): 'Alles zusammengenommen heißt das, dass Land,\ndas sich für den Reisanbau eignet,\ntendenzhalber weiter von aktiven Vulkanen entfernt liegt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_12'): 'Hmmm... Mit anderen Worten, ich habe mir\nzum Wohnen einen richtig eingelegten Pflaumenfleck ausgesucht.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_13'): 'Sind wir aber nicht Göttinnen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_14'): 'Mit meiner Intelligenz und deiner\nlandwirtschaftlichen Meisterschaft wird es wohl kein so\nschlechter Ort sein, auf dem nie etwas wächst.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_15'): 'Ho! Kämpferisch! Was schlägst du also vor?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_16'): 'Zusammengefasst, was wir gelernt haben:\nLand, das sich besser für den Reisanbau eignet,\nwird nur selten von Asche bedeckt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_17'): 'Doch "selten" heißt immer noch, dass es PASSIERT ist.\nMit anderen Worten, wir können mit Sicherheit sagen,\ndass die Zeit jeden Schaden auslöscht.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_18'): 'Die Zeit, hm?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_19'): 'Der Fluss der Zeit...\nDas ist etwas, was wir beeinflussen können.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_2'): '"Nahezu jeden Berg", sagst du?\nWie viele gibt es denn? Ein paar hundert?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_20'): 'Deshalb kommt die Verwandlungskugel\nins Spiel.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_21'): 'Die Verwandlungskugel?\nVom "Verwandlungspulver" habe ich gehört, aber...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_22'): 'Das Verwandlungspulver wird von der Kugel\nabgeschabt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_23'): 'Weil die Kugel ungleich mehr Kraft enthält,\nist es notwendig, die Erlaubnis von Lady\nKamuhitsuki einzuholen, um sie zu nutzen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_24'): 'Dann müssen wir das Eisen schmieden,\nsolange es heiß ist! Lass uns Lady Kamuhitsuki anflehen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_3'): 'Insgesamt dürften es etwa dreißigtausend\nsein. Die meisten davon liegen\nim Niedrigen Reich.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_4'): 'Waaas--?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_5'): 'So lächerlich diese Zahl auch ist, stört mich\nvielmehr, dass du sämtliche\nallein durchsucht hast...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_6'): 'Wie Tauemon sagte, gibt es anscheinend\neine Reihe von Vulkanen, die sich\ndurch Yanato erstrecken.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_7'): 'Ich bezweifle, dass es irgendeinen Boden gibt,\nden die Asche für immer verschont hat.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_8'): 'Das bedeutet, es gibt nur zwei Arten Land:\ndas, das sich von der Asche erholt hat,\nund das, das es nicht getan hat.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:06000403_9'): 'Genauso. Den näheren Vulkanen erging es schlechter,\nden etwas entfernten\ndagegen besser.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_0'): 'Was machst du hier?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_1'): 'Oh, Sakuna...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_10'): 'Hält er irgendwie ein Haustier\nhinter unserem Rücken?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_11'): 'Falls das stimmt, wäre es lästig, wenn er\nwieder in Schwierigkeiten geriete und gerettet werden müsste.\nLass uns ihm beim nächsten Mal folgen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_2'): 'Zuletzt verschwindet seltsamerweise immer mehr Essen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_3'): 'Hmmm... Sind Mäuse reingekommen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_4'): 'Ich sehe kein Tierfell oder keinen Kot.\nDas bedeutet...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_5'): 'Jemand nimmt sich zweite Portionen?\nDas sicherlich nicht ich!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_6'): 'Richtig! Du würdest dein Essen nicht verstecken!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_7'): 'Soll das ein Zeichen von Vertrauen sein...?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_8'): 'Könnte es Kaimaru sein?\nEr schleicht zuletzt irgendwie herum.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000101_9'): 'Wo wir gerade davon sprechen: Ich habe Kaimaru\nauch mit etwas gesehen, als er mit dem Hund loszog.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_0'): 'War das also wirklich das Werk von Kintas Schwert?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_1'): 'Kein Zweifel. Ich spürte dieselbe Kraft\nim Haus wie die, die im Schuppen war.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_10'): 'Ich habe mit dem Schmieden angefangen, weil ich Kraft wollte.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_11'): 'Aber missverstehe mich nicht. Als ich auf dem Metall\nhämmerte während unseres Aufenthalts hier, vergaß\nich all dieses dunkle Zeug.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_12'): 'Ich wollte... nur meine eigene Spur darauf hinterlassen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_13'): 'Ho ho ho! Oh, der strahlende Funke der Jugend.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_14'): 'Kannst du noch altertümlicher klingen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_15'): 'Ich glaube, das magische Schwert, das er erschuf,\nhat seine Gedanken aufgesogen und Eigenleben angenommen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_16'): 'Und um sich als die ultimative Waffe zu beweisen,\nhat es -- nein, es\nHAT Tauemons Schwert geschnitten.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_17'): 'Wie dreist, MICH zu ignorieren, das größte\nHeiligenschwert ganz Yanatos...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_18'): 'Ist es nicht so, weil du schon gebrochen bist?\nUnd außerdem bist du nur ein Griff.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_19'): 'Solche Frechheit...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_2'): 'Warum sollte es aber so etwas tun?\nEs hat ein anderes Schwert statt eines Menschen geschnitten.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_20'): 'Bedeutet das, es ist fort, um nach mehr\nSchwertern zu suchen, die es brechen kann?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_21'): 'Die einzigen anderen lobenswerten Schwerter auf der Insel\nsind... Ishimarus und die der Dämonen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_22'): 'Verglichen mit dem Klingen des Alten sind das\nnur Klumpen Metall.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_23'): 'Du warst an viel mehr Orten als wir.\nKannst du dir nichts anderes einfallen lassen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_24'): 'Hmmm... Was meinst du, Tama?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_25'): 'Mal sehen... Wie wäre damit: Wenn es sich\nnicht zeigt, behalten wir es im Auge,\nwährend wir die Insel bereisen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_26'): 'Ich kann kaum glauben, dass dieser Plan viel Mühe kostete.\nAber er schlägt das passive Herumsitzen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_27'): 'Bitte finde es! Ich bitte dich darum!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_28'): 'Meine Güte... Bist du nicht diejenige, die\n"Es ist vorbei!" gejammert hat, als das Haus zerstört wurde?\nDu änderst deine Meinung wirklich schnell.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_29'): 'Ich glaube, sie hat dich durchschaut, junger Mann.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_3'): 'Kinta, hattest du eine bestimmte Absicht,\nals du es machen wolltest?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_4'): 'Kraft. Ich wollte, dass es stark ist.\nSchärfer als jedes andere Schwert.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_5'): 'Warte einen Moment. Das klingt nach...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_6'): 'Ja, nach Ishimaru.\nIch wusste das eigentlich, aber...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_7'): 'Er mag der Räuber sein, der uns entführt hat, aber...\nIch kann dem, was er sagt, nicht widersprechen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_8'): 'Es gibt nicht gut oder böse, nur stark oder schwach.\nUnd die Schwachen werden gefressen. Das habe ich\nselbst gesehen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000304_9'): 'Kinta...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000701_0'): 'Yo, willkommen zurück.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000701_1'): 'Ah, perfektes Timing.\nIch habe einen Auftrag für dich.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000701_2'): 'Igitt... WAS ist das für ein Krach?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000701_3'): 'Prinzessin!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000701_4'): 'Wa--?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000701_5'): 'Eek!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000701_6'): 'Mein Schwert!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000701_7'): 'Mrrrgh!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:07000701_8'): 'Aaah!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_0'): 'So kann selbst unser strenger kleiner Bergpass\ndurch die geschäftige Menschlichkeit gedeihen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_1'): 'Scharen von Händlern kamen aus der Hauptstadt\nund richteten überall am Berg ihre Läden ein.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_10'): 'Ich sehe nicht, wie es persönliches Wachstum zählt,\nweiterhin Langeweile zu hassen...',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_11'): 'Yui, komm mal her!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_12'): 'Okaaay!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_13'): 'Bitte komm nach Sonnenuntergang nach Hause.\nEntspann dich bis dahin und hab Spaß.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_14'): 'Heehee!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_15'): 'Er sagt, Myrthe hat ein Festmahl\nfür dich fertig!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_2'): 'Wir haben sogar Soldaten für die Sicherheit geborgt\nund einfache Unterkünfte für den Anlass errichtet.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_3'): 'Wie rücksichtsvoll!\nUnd deshalb betrachte ich dich als meine liebe Freundin,\nKokorowa.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_4'): 'Da bist du also gewesen, Göttin.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_5'): 'Sah-Sah!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_6'): 'Oh? Brauchst du bei etwas Hilfe?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_7'): 'Du wirst gefeiert, also darfst du\nheute nicht arbeiten.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_8'): 'Das sagst du, aber ich bin ziemlich gelangweilt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000101_9'): 'Du hast dich erheblich verändert, Sakuna.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_0'): 'Prinzessin!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_1'): 'Ruhe euch, alle!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_10'): 'Der Reis, den ich hier angebaut habe, und das Lob,\ndas ihr ihm gegeben habt, haben Leib und Geist\ngleichsam mit unermesslicher Macht erfüllt!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_11'): 'Reis ist meine -- nein, die Seele des Volkes Yanatos\nselbst zum Ausdruck gebracht! Diese himmlischen Körner\nsind die Quelle unserer Kraft!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_12'): 'Kanalisiert eure Inbrunst in dieses heilige Ackerwerkzeug!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_13'): 'Mit diesem soll Omizuchi besiegt werden!\nFür die Herrlichkeit des Reises!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_2'): 'Es ist nur natürlich, Angst zu haben.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_3'): 'Aber weiche nicht dem Zorn des Berges aus,\nnoch dem bösen Gott Omizuchi, dessen Name\neinst selbst in der heiligen Hauptstadt Furcht erregte!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_4'): 'Seit er von meinem Vater Takeribi besiegt wurde,\nsitzt er lange tief in der Erde und schmiedet Pläne\nfür eine Rückkehr!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_5'): 'Und tatsächlich ist er endlich wieder zum Leben erwacht!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_6'): 'Mit der Kraft, die er angesammelt hat, zielt er darauf,\ndiese Insel zu zerstören, bevor er seinen bösen\nBlick der Hauptstadt zuwendet!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_7'): 'Aber seine vulgären Ambitionen bleiben unerfüllt!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_8'): 'Denn ich, Prinzessin Sakuna, Tochter des\ngroßen Takeribi, lehne mich trotzig auf!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_9'): 'Ich bin nicht mehr dieselbe faule Göttin,\ndie einst ihre Tage in der Hauptstadt vertrödelte.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_Choice'): 'Zum Haus gehen?',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000102_Pre_0'): 'Yui sagte, du sollst bis Sonnenuntergang nach Hause.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_0'): 'Wenn ich zurückblicke, habe ich einen langen Weg zurückgelegt.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_1'): 'Ich verspreche zurückzukehren. Dies ist mein Zuhause.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_Kaimaru_0'): 'Juhu!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_Kinta_0'): 'In Ordnung. Los und hol ihn dir.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_Kokorowa_0'): 'Außergewöhnlich. Wann bist du darauf gekommen?!',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_Kokorowa_1'): '*kichert*',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_Mirthe_0'): 'Ich habe dir ein Mittagessen gepackt. Bitte iss es\nunterwegs.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_Mirthe_1'): 'Wir warten hier auf dich.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_Tauemon_0'): 'Lady Sakuna, Lord Tama...\nMögen eure Anstrengungen die Frucht des Sieges tragen.',
    ('Text/Event/Mura/Soto/EventMain.csvtxt', 'English#c:08000103_Yui_0'): 'Sei vorsichtig, Göttin.',
}

